import sys
sys.path.append('storage')
import anndata as ad
from praxis.brbg_augmented import eliminate_augmented

def eliminate_batch_effect_fn(adata: ad.AnnData) -> ad.AnnData:
    return eliminate_augmented(adata, mode='interactions', l2=1e-3, use_cov1=False, use_cov2=True)
